import * as THREE from 'three';
import { createSiteScene, edgeFade, type Place, type SiteView } from '../SiteScene';
import { BOX, CONE, CYL, ROOF, TREE, instanced, mat, part, type Instance } from '../primitives';
import { LABEL_LIFT, LANDMARK_BUILDERS } from './landmarks';
import { LORE } from './lore';

// King's Landing, generated by tools/sites/kingsLanding/{plan,analyze}.mjs from the consensus city plan.
// Frame: metres, origin at the centre of the walls; city.json positions are [x, z, groundHeight].
type CityData = {
  size: [number, number];
  terrain: { cols: number; rows: number; step: number; h: number[] };
  wall: [number, number, number][];
  gates: Place[];
  landmarks: Place[];
  buildings: { stride: number; data: number[] };
  trees: { stride: number; data: number[] };
};
const DIR = '/sites/kingsLanding';

export async function createKingsLandingView(renderer: THREE.WebGLRenderer, labelsEl: HTMLElement): Promise<SiteView> {
  const data: CityData = await (await fetch(`${DIR}/city.json`)).json();
  const [SW, SH] = data.size, T = data.terrain;
  const EX = 1.5; // vertical exaggeration: scales the terrain mesh; everything else is seated on it

  const groundAt = (x: number, z: number) => { // metres, unexaggerated, bilinear on the terrain grid
    const fx = THREE.MathUtils.clamp((x + SW / 2) / T.step, 0, T.cols - 1.001);
    const fz = THREE.MathUtils.clamp((z + SH / 2) / T.step, 0, T.rows - 1.001);
    const c = Math.floor(fx), r = Math.floor(fz), tx = fx - c, tz = fz - r, i = r * T.cols + c, h = T.h;
    return (h[i] * (1 - tx) + h[i + 1] * tx) * (1 - tz) + (h[i + T.cols] * (1 - tx) + h[i + T.cols + 1] * tx) * tz;
  };
  const gy = (x: number, z: number) => groundAt(x, z) * EX;
  const maxGround = (x: number, z: number, r: number) => {
    let m = -Infinity;
    for (let dz = -r; dz <= r; dz += r / 4) for (let dx = -r; dx <= r; dx += r / 4) m = Math.max(m, gy(x + dx, z + dz));
    return m;
  };

  const site = createSiteScene(labelsEl, { id: 'kingsLanding', shadowExtent: 4500 });
  const { scene } = site;

  // ---------- terrain & water ----------
  const loadTex = (url: string) => {
    const t = new THREE.TextureLoader().load(url);
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = renderer.capabilities.getMaxAnisotropy();
    return t;
  };
  const terrainMat = edgeFade(mat(0xffffff, { map: loadTex(`${DIR}/ground.png`), roughness: 1 }));
  const terrain = new THREE.Mesh(new THREE.PlaneGeometry(1, 1, T.cols - 1, T.rows - 1), terrainMat);
  {
    const g = terrain.geometry;
    const pos = g.attributes.position as THREE.BufferAttribute, uv = g.attributes.uv as THREE.BufferAttribute;
    for (let i = 0; i < pos.count; i++) {
      const x = (i % T.cols) * T.step - SW / 2, z = Math.floor(i / T.cols) * T.step - SH / 2;
      pos.setXYZ(i, x, T.h[i], z);
      uv.setXY(i, (x + SW / 2) / SW, 1 - (z + SH / 2) / SH);
    }
    g.computeVertexNormals();
    terrain.receiveShadow = true;
  }
  const water = new THREE.Mesh(
    new THREE.PlaneGeometry(SW, SH).rotateX(-Math.PI / 2),
    edgeFade(mat(0x4f7584, { roughness: 0.2, metalness: 0.25, transparent: true, opacity: 0.9 })),
  );
  water.receiveShadow = true;
  scene.add(terrain, water);

  // ---------- generated content ----------
  function houses() {
    const d = data.buildings.data, S = data.buildings.stride, bodies: Instance[] = [], roofs: Instance[] = [];
    for (let k = 0; k < d.length; k += S) {
      const [x, z, y, w, dd, hh, rot, roofC, wallC] = d.slice(k, k + S);
      const base = y * EX;
      bodies.push({ pos: new THREE.Vector3(x, base - 3, z), rot, scale: new THREE.Vector3(w, hh + 3, dd), color: wallC });
      roofs.push({ pos: new THREE.Vector3(x, base + hh, z), rot, scale: new THREE.Vector3(w * 1.06, Math.min(w, dd) * 0.5, dd * 1.12), color: roofC });
    }
    const g = new THREE.Group();
    g.add(instanced(BOX, mat(0xffffff, { roughness: 0.95 }), bodies), instanced(ROOF, mat(0xffffff, { roughness: 0.8 }), roofs));
    return g;
  }

  function trees() {
    const d = data.trees.data, items: Instance[] = [];
    for (let k = 0; k < d.length; k += data.trees.stride) {
      const [x, z, y, s] = d.slice(k, k + 4);
      items.push({
        pos: new THREE.Vector3(x, y * EX + 5 * s, z), rot: k * 1.7, scale: new THREE.Vector3(6 * s, 8 * s, 6 * s),
        color: new THREE.Color().setHSL(0.22 + ((k * 13) % 7) / 100, 0.4, 0.22 + ((k * 7) % 5) / 50).getHex(),
      });
    }
    return instanced(TREE, mat(0xffffff, { flatShading: true, roughness: 1 }), items);
  }

  function walls() {
    const out = new THREE.Group(), pts = data.wall, segs: Instance[] = [], towers: Instance[] = [], caps: Instance[] = [];
    const stone = mat(0xb9a47f, { roughness: 0.95 });
    for (let i = 0; i < pts.length; i++) {
      const [ax, az, ay] = pts[i], [bx, bz, by] = pts[(i + 1) % pts.length];
      const len = Math.hypot(bx - ax, bz - az), rot = -Math.atan2(bz - az, bx - ax);
      const base = Math.min(ay, by) * EX - 6, top = Math.max(ay, by) * EX + 15;
      segs.push({ pos: new THREE.Vector3((ax + bx) / 2, base, (az + bz) / 2), rot, scale: new THREE.Vector3(len + 3, top - base, 7) });
      const n = Math.max(1, Math.round(len / 95));
      for (let t = 0; t < n; t++) {
        const x = ax + ((bx - ax) * t) / n, z = az + ((bz - az) * t) / n, y = gy(x, z);
        towers.push({ pos: new THREE.Vector3(x, y - 6, z), rot: 0, scale: new THREE.Vector3(7, 27, 7) });
        caps.push({ pos: new THREE.Vector3(x, y + 21, z), rot: 0, scale: new THREE.Vector3(8.3, 3, 8.3) });
      }
    }
    out.add(instanced(BOX, stone, segs), instanced(CYL, stone, towers), instanced(CYL, mat(0xa8936e), caps));

    const gateStone = mat(0xa89070), dark = mat(0x3a2e24), roof = mat(0x6b5047);
    for (const g of data.gates) {
      const [x, z, y] = g.pos;
      let best = Infinity, rot = 0; // align the gatehouse with the nearest wall segment
      for (let i = 0; i < pts.length; i++) {
        const [ax, az] = pts[i], [bx, bz] = pts[(i + 1) % pts.length];
        const d = Math.hypot((ax + bx) / 2 - x, (az + bz) / 2 - z);
        if (d < best) { best = d; rot = -Math.atan2(bz - az, bx - ax); }
      }
      const grp = new THREE.Group();
      grp.position.set(x, y * EX, z);
      grp.rotation.y = rot;
      grp.add(part(BOX, gateStone, 0, -6, 0, 30, 34, 18), part(BOX, dark, 0, -1, 0, 9, 12, 18.5));
      for (const s of [-1, 1]) grp.add(part(CYL, gateStone, s * 17, -6, 0, 9, 38, 9), part(CONE, roof, s * 17, 32, 0, 10, 12, 10));
      out.add(grp);
    }
    return out;
  }

  function landmarks() {
    const out = new THREE.Group();
    for (const p of data.landmarks) {
      const build = LANDMARK_BUILDERS[p.kind];
      if (!build) continue;
      const [x, z] = p.pos, r = p.radius || 30;
      const g = build(r);
      g.position.set(x, p.kind === 'square' ? gy(x, z) : maxGround(x, z, r * 0.5), z);
      out.add(g);
    }
    return out;
  }

  terrain.scale.y = EX;
  scene.add(houses(), trees(), walls(), landmarks());
  const places = [...data.gates, ...data.landmarks];
  site.addPlaces(places);
  for (const l of site.labelObjs) l.obj.position.y = l.place.pos[2] * EX + (LABEL_LIFT[l.place.kind] ?? 25);

  return Object.assign(site, {
    lore: LORE,
    focus: (p: Place) => ({ x: p.pos[0], z: p.pos[1], alt: Math.max(260, (p.radius || 40) * 4.5) * 0.7 }),
  });
}
